import {supabase} from './auth-client.mjs';
import {playerParameters,playerLink} from './player-model.mjs';
import {selectedAlbumSet} from './player-album-model.mjs?v=foil1';
import {createAlbumPage} from './album-page-view.mjs?v=foil1';
const view=createAlbumPage(),root=new URL('./album-data/',import.meta.url);let preview=false,player,data,selected=0;
try{preview=['localhost','127.0.0.1','[::1]'].includes(location.hostname)&&new URL(location.href).searchParams.get('preview')==='1';const params=preview?{album:4}:playerParameters(location.href,import.meta.url);if(!Number.isInteger(params.album)||params.album<1||params.album>32767)throw Error('Invalid album.');if(preview){player={name:'Sample collector',uid:'18691234',season:'autumn-tales',inventory:[1,2,3,4,5,6,7,8,9,55,56,57,59,60,61,91,92,93,95].map(n=>({card_number:n,quantity:[2,93,95].includes(n)?2:1,has_foil:[2,91].includes(n),trade_foil:false}))}}else{const {data:result,error}=await supabase.rpc('get_player_album',{p_uid:params.uid,p_album:params.album});if(error)throw Error('Player albums are not available yet.');if(!result)throw Error('This player album is private or was not found.');player=result}if(player.season!=='autumn-tales')throw Error('This album is not supported yet.');const response=await fetch(new URL('autumn-tales.json',root));if(!response.ok)throw Error('Album data could not load.');data=await response.json();selected=selectedAlbumSet(location.href,data.sets.length);if(!preview){const url=new URL(playerLink(player.uid,params.album,import.meta.url));if(selected)url.searchParams.set('set',selected);history.replaceState(null,'',url)}view.status('');view.setCollection(data,{uid:player.uid},new Map(player.inventory.map(item=>[item.card_number,item.quantity])),{initial:true,foilRows:new Map(player.inventory.map(row=>[row.card_number,row]))})}catch(error){view.status(error.message)}
